'use client';

import React, { useEffect, useRef, useState } from 'react';

const benchmarkData = [
  { steps: '1,024', proverWork: '0.004 s', proofGen: '0.140 s', verify: '0.001 s', proofSize: '118 KB' },
  { steps: '4,096', proverWork: '0.017 s', proofGen: '0.588 s', verify: '0.001 s', proofSize: '133 KB' },
  { steps: '16,384', proverWork: '0.092 s', proofGen: '2.666 s', verify: '0.017 s', proofSize: '145 KB' },
  { steps: '65,536', proverWork: '0.252 s', proofGen: '11.794 s', verify: '0.001 s', proofSize: '163 KB' },
];

const highlights = [
  { value: 'Linear scaling', desc: 'Prover work scales linearly — required property for a secure VDF' },
  { value: '<170 KB', desc: 'Proof size remains compact regardless of delay length' },
  { value: 'No trusted setup', desc: 'STARKs require zero ceremony — fully transparent and reproducible' },
];

export default function BenchmarksSection() {
  const [visibleRows, setVisibleRows] = useState<number[]>([]);
  const [sectionVisible, setSectionVisible] = useState(false);
  const sectionRef = useRef<HTMLDivElement>(null);
  const headerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setSectionVisible(true);
            benchmarkData.forEach((_, i) => {
              setTimeout(() => {
                setVisibleRows((prev) => [...prev, i]);
              }, 200 + i * 120);
            });
            observer.disconnect();
          }
        });
      },
      { threshold: 0.2 }
    );
    if (sectionRef.current) observer.observe(sectionRef.current);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) entry.target.classList.add('visible');
        });
      },
      { threshold: 0.15 }
    );
    if (headerRef.current) observer.observe(headerRef.current);
    return () => observer.disconnect();
  }, []);

  return (
    <section id="benchmarks" className="py-20 relative overflow-hidden">
      {/* Background */}
      <div className="absolute inset-0 bg-gradient-to-b from-transparent via-muted/20 to-transparent pointer-events-none" />
      <div className="absolute left-0 top-1/2 w-[300px] h-[300px] blob-primary opacity-[0.07] animate-blob-float pointer-events-none" />

      <div className="max-w-7xl mx-auto px-6 lg:px-8">
        {/* Header */}
        <div ref={headerRef} className="reveal text-center max-w-2xl mx-auto mb-14">
          <span className="text-xs font-bold tracking-widest uppercase text-primary font-mono mb-3 block">
            Real Data. No Estimates.
          </span>
          <h2 className="text-display font-extrabold text-foreground mb-4">
            Live Benchmarks
          </h2>
          <p className="text-lg text-muted-foreground leading-relaxed">
            Verifier time stays constant at{' '}
            <span className="text-primary font-bold font-mono">~1 millisecond</span>{' '}
            even as prover workload scales 64×.
          </p>
        </div>

        {/* Benchmark Table */}
        <div
          ref={sectionRef}
          className={`glass-card rounded-3xl overflow-hidden border border-border transition-all duration-700 ${
            sectionVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-8'
          }`}
        >
          {/* Table header */}
          <div className="grid grid-cols-5 bg-muted/50 border-b border-border px-6 py-4">
            {['Delay Steps', 'Prover Work Time', 'Proof Generation', 'Verify Time', 'Proof Size'].map((col, i) => (
              <div key={col} className={`text-xs font-bold uppercase tracking-widest font-mono ${i === 3 ? 'text-primary' : 'text-muted-foreground'}`}>
                {col}
                {i === 3 && <span className="ml-1.5 text-primary">★</span>}
              </div>
            ))}
          </div>

          {/* Table rows */}
          {benchmarkData.map((row, i) => (
            <div
              key={row.steps}
              className={`grid grid-cols-5 px-6 py-5 border-b border-border/50 last:border-0 table-row-hover transition-all duration-500 ${
                visibleRows.includes(i)
                  ? 'opacity-100 translate-x-0' :'opacity-0 -translate-x-4'
              }`}
            >
              <div className="font-data text-sm font-bold text-foreground">{row.steps}</div>
              <div className="font-data text-sm text-muted-foreground">{row.proverWork}</div>
              <div className="font-data text-sm text-muted-foreground">{row.proofGen}</div>
              <div className="font-data text-sm font-bold text-primary">
                <span className="inline-flex items-center gap-1.5">
                  <span className="w-1.5 h-1.5 rounded-full bg-primary inline-block" />
                  {row.verify}
                </span>
              </div>
              <div className="font-data text-sm text-muted-foreground">{row.proofSize}</div>
            </div>
          ))}

          {/* Footer note */}
          <div className="px-6 py-4 bg-muted/20 border-t border-border">
            <p className="text-xs text-muted-foreground font-mono">
              Benchmarks run on commodity hardware. Rust + Winterfell 0.13 STARK library. 128-bit prime field, 256 constraints, degree-2 AIR.
            </p>
          </div>
        </div>

        {/* Highlights */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-5 mt-8">
          {highlights.map((h, i) => (
            <div
              key={h.value}
              className={`glass-card rounded-2xl p-5 border border-border/60 transition-all duration-700 ${
                sectionVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-8'
              }`}
              style={{ transitionDelay: `${600 + i * 100}ms` }}
            >
              <p className="font-data text-lg font-bold text-primary mb-1">{h.value}</p>
              <p className="text-sm text-muted-foreground leading-relaxed">{h.desc}</p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}