'use client';

import React, { useEffect, useRef } from 'react';

const features = [
  {
    feature: 'Mathematical Basis',
    rule30: 'Rule 30 cellular automaton (40+ years empirical study)',
    traditional: 'RSA groups, class groups',
    highlight: true,
  },
  {
    feature: 'Trusted Setup',
    rule30: 'None — fully transparent',
    traditional: 'Often required',
    highlight: false,
  },
  {
    feature: 'Quantum Resistance',
    rule30: 'Yes (STARK-based)',
    traditional: 'Generally no',
    highlight: true,
  },
  {
    feature: 'Proof System',
    rule30: 'STARKs via audited Winterfell 0.13',
    traditional: 'Pietrzak, Wesolowski, etc.',
    highlight: false,
  },
  {
    feature: 'Hardness Assumption',
    rule30: 'Computational irreducibility conjecture',
    traditional: 'Factoring / group order',
    highlight: true,
  },
];

export default function DifferentiationSection() {
  const headerRef = useRef<HTMLDivElement>(null);
  const tableRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) entry.target.classList.add('visible');
        });
      },
      { threshold: 0.1 }
    );
    if (headerRef?.current) observer?.observe(headerRef?.current);
    if (tableRef?.current) observer?.observe(tableRef?.current);
    return () => observer?.disconnect();
  }, []);

  return (
    <section id="differentiation" className="py-20 relative overflow-hidden">
      <div className="absolute right-0 top-1/3 w-[350px] h-[350px] blob-accent opacity-[0.06] animate-blob-float-alt pointer-events-none" />
      <div className="max-w-7xl mx-auto px-6 lg:px-8">
        {/* Header */}
        <div ref={headerRef} className="reveal text-center max-w-2xl mx-auto mb-14">
          <span className="text-xs font-bold tracking-widest uppercase text-primary font-mono mb-3 block">
            The Competitive Edge
          </span>
          <h2 className="text-display font-extrabold text-foreground mb-4">
            Why Rule 30 VDF Stands Apart
          </h2>
          <p className="text-lg text-muted-foreground leading-relaxed">
            Every VDF relies on mathematical assumptions. Rule 30&apos;s assumption benefits from
            four decades of rigorous study with no known breaks.
          </p>
        </div>

        {/* Comparison Table */}
        <div
          ref={tableRef}
          className="reveal glass-card rounded-3xl overflow-hidden border border-border"
        >
          {/* Table Header */}
          <div className="grid grid-cols-3 border-b border-border">
            <div className="px-6 py-4 text-xs font-bold uppercase tracking-widest text-muted-foreground font-mono border-r border-border">
              Feature
            </div>
            <div className="px-6 py-4 col-highlight border-r border-primary/20">
              <div className="flex items-center gap-2">
                <span className="w-2 h-2 rounded-full bg-primary" />
                <span className="text-xs font-bold uppercase tracking-widest text-primary font-mono">
                  Rule 30 VDF (This Project)
                </span>
              </div>
            </div>
            <div className="px-6 py-4 text-xs font-bold uppercase tracking-widest text-muted-foreground font-mono">
              Traditional VDFs
            </div>
          </div>

          {/* Rows */}
          {features?.map((row, i) => (
            <div
              key={row?.feature}
              className="grid grid-cols-3 border-b border-border/60 last:border-0 table-row-hover"
            >
              <div className="px-6 py-5 border-r border-border">
                <span className="text-sm font-semibold text-foreground">{row?.feature}</span>
              </div>
              <div className="px-6 py-5 col-highlight border-r border-primary/20">
                <div className="flex items-start gap-2">
                  {row?.highlight && (
                    <svg className="w-4 h-4 text-primary flex-shrink-0 mt-0.5" fill="currentColor" viewBox="0 0 20 20">
                      <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" />
                    </svg>
                  )}
                  <span className="text-sm text-foreground font-medium leading-relaxed">{row?.rule30}</span>
                </div>
              </div>
              <div className="px-6 py-5">
                <span className="text-sm text-muted-foreground leading-relaxed">{row?.traditional}</span>
              </div>
            </div>
          ))}
        </div>

        {/* Footnote */}
        <div className="mt-6 glass-card-light rounded-xl p-4 border border-border/60">
          <p className="text-sm text-muted-foreground leading-relaxed text-center">
            <span className="text-foreground font-medium">All VDF constructions rely on mathematical assumptions.</span>{' '}
            Rule 30&apos;s assumption benefits from four decades of rigorous study with no known breaks —
            comparable to the factoring assumption underlying RSA.
          </p>
        </div>
      </div>
    </section>
  );
}